package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;

final class FieldDispatchBrowserAcceptance {
 static void run(BrowserTest h)throws Exception {
  String parent,task,technician;
  try(var db=h.store.open()){
   String admin=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","FieldBrowserTechnician","role","agent","password",WorkflowSupport.PASSWORD));technician=RecordAccess.owner(db,"FieldBrowserTechnician");
   String group=Service.create(db,"sys_user_group",map("short_description","Regional field team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,technician);
   parent=Service.create(db,"incident",map("short_description","Restore the customer terminal"),"admin").get("sys_id").toString();WorkTasks.command(db,"incident",parent,map("operation","configure","revision",0,"record_revision",0,"close_at","6"));
   task=objects(WorkTasks.command(db,"incident",parent,map("operation","create","revision",1,"record_revision",1,"summary","Inspect the terminal <script>","details","Visit reception, inspect the terminal and verify the result.","group_id",group,"required",true,"predecessors",List.of())).get("tasks")).getFirst().get("task_id").toString();
   ServiceClocks.calendar(db,admin,map("name","FieldBrowserDay","calendar",map("zone","UTC","start","08:00","end","18:00","days",List.of(1,2,3,4,5),"holidays",List.of())));db.connection.commit();
  }
  try(var p=Playwright.create();var browser=p.chromium().launch();var adminContext=browser.newContext();var technicianContext=browser.newContext()){
   var page=adminContext.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Field service").setExact(true)).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Technician availability").setExact(true)).press("Enter");page.getByLabel("Technician",new Page.GetByLabelOptions().setExact(true)).selectOption("FieldBrowserTechnician");page.getByLabel("Business calendar",new Page.GetByLabelOptions().setExact(true)).selectOption("FieldBrowserDay");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Configure technician availability")).press("Enter");page.locator("article").filter(new Locator.FilterOptions().setHasText("FieldBrowserTechnician")).getByLabel("Dispatch availability").selectOption("false");page.locator("article").filter(new Locator.FilterOptions().setHasText("FieldBrowserTechnician")).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Save availability")).press("Enter");page.locator("article").filter(new Locator.FilterOptions().setHasText("FieldBrowserTechnician")).getByLabel("Dispatch availability").selectOption("true");page.locator("article").filter(new Locator.FilterOptions().setHasText("FieldBrowserTechnician")).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Save availability")).press("Enter");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-availability-light.png")).setFullPage(true));
   page.navigate(h.base()+"/record/incident/"+parent+"/work-tasks");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Dispatch field visit")).press("Enter");page.getByLabel("Technician",new Page.GetByLabelOptions().setExact(true)).selectOption(technician);page.getByLabel("Visit location").fill("Building A reception <script>alert(1)</script>");page.getByLabel("Visit start (UTC)").fill("2030-01-07T09:00:00Z");page.getByLabel("Visit end (UTC)").fill("2030-01-07T10:00:00Z");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-dispatch-light.png")).setFullPage(true));page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Assign field visit")).press("Enter");assertThat(page.locator("main")).containsText("Assigned · FieldBrowserTechnician");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to case tasks")).press("Enter");assertThat(page.locator("#task-"+task).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Claim task").setExact(true))).hasCount(0);assertThat(page.locator("#task-"+task).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Cancel task").setExact(true))).hasCount(0);page.locator("#task-"+task).getByRole(AriaRole.LINK,new Locator.GetByRoleOptions().setName("Dispatch field visit")).press("Enter");
   var worker=technicianContext.newPage();h.login(worker,"FieldBrowserTechnician");worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Field service").setExact(true)).press("Enter");worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inspect the terminal <script> · assigned")).press("Enter");worker.getByLabel("Decision reason").fill("Customer asked for a revised visit");worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Reject field visit")).press("Enter");assertThat(worker.locator("main")).containsText("Rejected");page.reload();page.getByLabel("Technician",new Page.GetByLabelOptions().setExact(true)).selectOption(technician);page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Assign field visit")).press("Enter");worker.reload();worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");worker.setViewportSize(390,844);worker.getByLabel("Decision reason").fill("Visit confirmed with reception");ReleaseBrowserAcceptance.accessible(worker);assertThat(worker.locator("main script")).hasCount(0);assertEquals(false,worker.evaluate("document.documentElement.scrollWidth>window.innerWidth"));worker.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-dispatch-dark.png")).setFullPage(true));worker.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Accept field visit")).press("Enter");assertThat(worker.locator("main")).containsText("Accepted");worker.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Back to case tasks")).press("Enter");worker.locator("#task-"+task).getByLabel("Completion outcome").fill("Terminal repaired and checked with reception");worker.locator("#task-"+task).getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");worker.locator("#task-"+task).getByRole(AriaRole.LINK,new Locator.GetByRoleOptions().setName("Dispatch field visit")).press("Enter");assertThat(worker.locator("main")).containsText("Complete · FieldBrowserTechnician");ReleaseBrowserAcceptance.accessible(worker);worker.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/field-completed-dark.png")).setFullPage(true));
  }
 }
}
